<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();$c=obtener_caso((int)$_GET['caso']);$id=(int)$_GET['id'];$s=bd()->prepare('SELECT * FROM archivos_caso WHERE id_archivo=? AND id_caso=?');$s->bind_param('ii',$id,$c['id_caso']);$s->execute();$a=$s->get_result()->fetch_assoc();if(!$a)exit('Archivo inexistente');header('Content-Type: '.$a['tipo_mime']);header('Content-Disposition: attachment; filename="'.basename($a['nombre_original']).'"');echo $a['contenido'];